$ErrorActionPreference='Stop';$p=Join-Path $PSScriptRoot '..\Contracts\es-external-agent-supply-chain-v1.json';$j=Get-Content -Raw -Encoding UTF8 $p|ConvertFrom-Json;$ids=@($j.frameworks|% frameworkId);$required=@('langgraph','letta','openhands','swe-agent');$bad=@($required|?{$_ -notin $ids});$badFields=@($j.frameworks|?{[string]::IsNullOrWhiteSpace($_.sourceUrl)-or[string]::IsNullOrWhiteSpace($_.status)-or[string]::IsNullOrWhiteSpace($_.driftAction)});$ok=($bad.Count -eq 0 -and $badFields.Count -eq 0 -and @($ids|sort -Unique).Count -eq $ids.Count);[pscustomobject]@{schemaVersion=1;validator='Test-ESSupplyChainContract';status=$(if($ok){'passed'}else{'failed'});frameworkCount=$j.frameworks.Count;frameworks=$ids;policy=$j.policy;runtimeStatus='runtime-not-run';claimsNotProven=@('License approval','source revision/hash freeze','external runtime')}|ConvertTo-Json -Depth 8;if(-not $ok){exit 1}
